	function lines(value: string | null) { return value?.split(/\r?\n|,/).map((x)=>x.trim()).filter(Boolean) ?? []; }
	const applicationState = $derived(({open:'Open',upcoming:'Upcoming',closed:'Closed',unconfirmed:'Status not confirmed'} as const)[item.applicationStatus]);
